using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
public static class GridShiftV23Setup {
 public static void Batch(){Directory.CreateDirectory("Docs/Validacao23");Directory.CreateDirectory("Assets/Generated/Home23");EditorSceneManager.OpenScene("Assets/Scenes/Apartment.unity");var house=Object.FindFirstObjectByType<GridShiftApartment>();if(house.GetComponent<GridShiftApartmentView>()==null)house.gameObject.AddComponent<GridShiftApartmentView>();house.GetComponent<GridShiftApartmentView>().doorway=new Vector3(-2.5f,0,-8.7f);int fixedBoxes=0;var cube=GameObject.CreatePrimitive(PrimitiveType.Cube);var source=cube.GetComponent<MeshFilter>().sharedMesh;var vertices=source.vertices;var triangles=source.triangles;Object.DestroyImmediate(cube);foreach(var box in house.GetComponentsInChildren<BoxCollider>(true)){var scale=box.transform.lossyScale;if(scale.x>=0&&scale.y>=0&&scale.z>=0)continue;string path="Assets/Generated/Home23/MirroredCollider-"+(fixedBoxes++)+".asset";var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(mesh==null){mesh=new Mesh{name="Mirrored kit collider"};mesh.vertices=vertices.Select(v=>box.center+Vector3.Scale(v,box.size)).ToArray();mesh.triangles=triangles;mesh.RecalculateBounds();mesh.RecalculateNormals();AssetDatabase.CreateAsset(mesh,path);}var collider=box.gameObject.AddComponent<MeshCollider>();collider.sharedMesh=mesh;collider.sharedMaterial=box.sharedMaterial;collider.convex=box.isTrigger;collider.isTrigger=box.isTrigger;collider.enabled=box.enabled;Object.DestroyImmediate(box);}var wall=house.transform.Find("Hallway/Walls/Int_Apt_02_Wall_01 (6)");if(wall!=null){foreach(var r in wall.GetComponents<Renderer>())r.enabled=false;foreach(var c in wall.GetComponents<Collider>())c.enabled=false;}if(house.transform.Find("Terrace doorway frame")==null){var frame=new GameObject("Terrace doorway frame");frame.transform.SetParent(house.transform,false);var material=AssetDatabase.LoadAssetAtPath<Material>("Assets/Generated/Home23/Plaster.mat");if(material==null){material=new Material(Shader.Find("Universal Render Pipeline/Lit")){color=new Color(.76f,.78f,.8f)};AssetDatabase.CreateAsset(material,"Assets/Generated/Home23/Plaster.mat");}foreach(float side in new[]{-1f,1f})Part(frame.transform,new Vector3(-2.5f+side*.925f,2,-6.2f),new Vector3(.65f,4,.12f),material);Part(frame.transform,new Vector3(-2.5f,3.32f,-6.2f),new Vector3(1.2f,1.36f,.12f),material);}foreach(var r in house.GetComponentsInChildren<MeshRenderer>(true)){var b=r.bounds;if(r.name.Contains("Wall")&&Mathf.Abs(b.center.z+6.2f)<.4f&&Mathf.Abs(b.center.x+2.5f)<.6f&&b.size.z<.8f&&b.size.y>2.5f){r.enabled=false;foreach(var c in r.GetComponents<Collider>())c.enabled=false;}}foreach(var r in house.GetComponentsInChildren<MeshRenderer>(true)){var b=r.bounds;if(r.name.Contains("Wall")&&Mathf.Abs(b.center.z+8.7f)<.4f&&Mathf.Abs(b.center.x+2.5f)<.6f&&b.size.z<.8f&&b.size.y>2.5f){r.enabled=false;foreach(var c in r.GetComponents<Collider>())c.enabled=false;}}if(house.transform.Find("Terrace exterior doorframe")==null){var frame=new GameObject("Terrace exterior doorframe");frame.transform.SetParent(house.transform,false);var material=AssetDatabase.LoadAssetAtPath<Material>("Assets/Generated/Home23/Plaster.mat");foreach(float side in new[]{-1f,1f})Part(frame.transform,new Vector3(-2.5f+side*.925f,2,-8.7f),new Vector3(.65f,4,.12f),material);Part(frame.transform,new Vector3(-2.5f,3.32f,-8.7f),new Vector3(1.2f,1.36f,.12f),material);}Physics.SyncTransforms();bool opening=!Physics.Raycast(new Vector3(-2.5f,1.2f,-5.7f),Vector3.back,1.2f,~((1<<7)|(1<<8)|(1<<9)),QueryTriggerInteraction.Ignore);File.WriteAllText("Docs/Validacao23/setup.txt","Mirrored boxes converted="+fixedBoxes+"\nSouth hallway opening free="+opening+"\n");EditorSceneManager.SaveScene(house.gameObject.scene);AssetDatabase.SaveAssets();EditorApplication.Exit(opening?0:2);}
 static void Part(Transform parent,Vector3 at,Vector3 size,Material material){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name="Doorway frame";g.transform.SetParent(parent,false);g.transform.localPosition=at;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=material;}}
